const photos = Array.isArray($json.photos) ? $json.photos.filter(Boolean) : [];
if (photos.length === 0) throw new Error('Pexels no devolvio fotos');

const shuffled = [...photos].sort(() => Math.random() - 0.5);
const featuredPhoto = shuffled[0];
const inlinePhoto = shuffled.find((photo) => photo.id !== featuredPhoto.id) || featuredPhoto;

return [{ json: { featuredPhoto, inlinePhoto } }];

