const input = $('Execute Workflow Trigger').first().json;
const currentItem = items[0];

const userRaw = input.wpUser;
const passRaw = input.wpPassword;
const user = (Array.isArray(userRaw) ? userRaw[0] : userRaw || 'admonwp').toString().trim();
const passClean = (Array.isArray(passRaw) ? passRaw[0] : passRaw || '').toString().replace(/\s+/g, '').trim();
const headerAuthRaw = `Basic ${Buffer.from(`${user}:${passClean}`, 'utf8').toString('base64')}`;

const topic = (input.topic || 'blog').toString().trim();
const imageBase = topic
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s]/g, '')
  .replace(/\s+/g, '-')
  .slice(0, 52) || 'blog';

return [{
  json: {
    ...(currentItem.json || {}),
    headerAuthRaw,
    inlineImageName: `${imageBase}-detalle.jpg`,
    inlineAlt: topic || imageBase,
    inlineTitle: input.title || topic || imageBase
  },
  binary: currentItem.binary
}];

const input = $('Execute Workflow Trigger').first().json;
const article = {
  content: (input.content || input.text || '').toString(),
  excerpt: (input.excerpt || '').toString()
};
const inlineNode = $('Patch imagen inline SEO').first().json;
const inlineUrl = inlineNode.source_url || (inlineNode.guid && inlineNode.guid.rendered) || '';
const inlineAlt = ($('Auth imagen inline').first().json.inlineAlt || input.topic || 'Imagen del articulo').toString().replace(/&/g, '&amp;').replace(/"/g, '&quot;').trim();
const inlineId = $('Subir imagen inline').first().json.id;
const originalWidth = Number(inlineNode.media_details?.width || 0);
const originalHeight = Number(inlineNode.media_details?.height || 0);
const inlineWidth = originalWidth > 0 ? Math.max(1, Math.round(originalWidth * 0.3)) : 384;
const inlineHeight = originalHeight > 0 ? Math.max(1, Math.round(originalHeight * 0.3)) : 216;
const figure = inlineUrl ? `<figure class="wp-block-image size-medium" style="text-align:center;margin-left:auto;margin-right:auto;"><img src="${inlineUrl}" alt="${inlineAlt}" class="wp-image-${inlineId}" width="${inlineWidth}" height="${inlineHeight}" loading="lazy" style="width:${inlineWidth}px;height:${inlineHeight}px;max-width:100%;display:block;margin-left:auto;margin-right:auto;" /></figure>` : '';

// --- SANITIZAR ENLACES MALFORMADOS ---
function sanitizeLinks(html) {
  return html
    .replace(/href="+(https?:\/\/[^\s"<>]+?)"+/gi, 'href="$1"')
    .replace(/href="&quot;(https?:\/\/[^\s"<>&]+?)&quot;"/gi, 'href="$1"')
    .replace(/href="%22(https?:\/\/[^\s"<>]+?)%22"/gi, 'href="$1"');
}

// --- INSERTAR IMAGEN EN LÍMITE DE BLOQUE ---
const finalContent = (() => {
  if (!article.content || !figure) return article.content;

  const html = sanitizeLinks(article.content);
  const totalLen = html.length;
  const midPoint = Math.floor(totalLen / 2);

  const blockBoundaries = [];
  const blockEndPattern = /<\/(?:p|section|ol|ul|table|dl|blockquote|aside|figure)>\s*/gi;
  let m;
  while ((m = blockEndPattern.exec(html)) !== null) {
    const pos = m.index + m[0].length;
    blockBoundaries.push(pos);
  }

  if (blockBoundaries.length > 0) {
    let bestPos = blockBoundaries[0];
    let bestDist = Math.abs(bestPos - midPoint);
    for (const pos of blockBoundaries) {
      const dist = Math.abs(pos - midPoint);
      if (dist < bestDist) { bestDist = dist; bestPos = pos; }
    }
    const tooEarly = bestPos < totalLen * 0.2;
    const tooLate  = bestPos > totalLen * 0.8;
    if (!tooEarly && !tooLate) {
      return html.slice(0, bestPos) + figure + html.slice(bestPos);
    }
  }

  const paragraphs = [...html.matchAll(/<p\b[^>]*>[\s\S]*?<\/p>/gi)];
  if (paragraphs.length === 0) return html + figure;
  const middleIndex = Math.max(0, Math.floor(paragraphs.length / 2) - 1);
  const target = paragraphs[middleIndex];
  const insertAt = (target.index ?? 0) + target[0].length;
  return html.slice(0, insertAt) + figure + html.slice(insertAt);
})();

const excerpt = article.excerpt || finalContent.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 155);

return [{
  json: {
    headerAuthRaw: $('Auth imagen principal').first().json.headerAuthRaw,
    featuredMediaId: $('Subir imagen principal').first().json.id,
    featuredAlt: $('Auth imagen principal').first().json.pexelsAlt,
    content: finalContent,
    excerpt,
    inlineImageId: inlineId,
    inlineUrl,
    inlineAlt
  }
}];
